-- The pools of a sheet, each (trimmed) name at most once, and their members: people of the sheet,
-- each at most once in a pool, with a share percent. A person can be in several pools.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    CONSTRAINT pool_unique UNIQUE (sheet_id, name)
);

CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL,
    CONSTRAINT pool_member_unique UNIQUE (pool_id, person_id)
);
-- A pool member may be another pool of the sheet instead of a person: exactly one of person_id and
-- member_pool_id is set. A pool is a member of at most one pool.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
ALTER TABLE pool_member ADD CONSTRAINT pool_member_pool_unique UNIQUE (member_pool_id);
-- A pool membership may carry a from-date and a to-date (both optional, inclusive): a member whose
-- dates do not include the sheet's today is left out of the pool.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
-- The crews of a sheet, each (trimmed) name at most once, each with a lead chosen from the people,
-- and their members: people of the sheet, each at most once in a crew and never its lead. People are
-- held by id only, so a person leaving the sheet just drops out of the crews.
CREATE TABLE crew (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name           VARCHAR(200) NOT NULL,
    lead_person_id BIGINT       NOT NULL,
    CONSTRAINT crew_unique UNIQUE (sheet_id, name)
);

CREATE TABLE crew_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    crew_id   BIGINT NOT NULL REFERENCES crew (id),
    person_id BIGINT NOT NULL,
    CONSTRAINT crew_member_unique UNIQUE (crew_id, person_id)
);
-- A crew is also a pool: a pool row of the sheet under the crew's name, marked with its crew. Its
-- members are not stored: they are the crew's lead and members, at equal shares. The pool's name
-- being unique on the sheet, a pool and a crew never share a name.
ALTER TABLE pool ADD COLUMN crew_id BIGINT REFERENCES crew (id);
ALTER TABLE pool ADD CONSTRAINT pool_crew_unique UNIQUE (crew_id);
INSERT INTO pool (sheet_id, name, crew_id)
SELECT c.sheet_id, c.name, c.id FROM crew c
WHERE NOT EXISTS (SELECT 1 FROM pool p WHERE p.sheet_id = c.sheet_id AND p.name = c.name)
ORDER BY c.id;
